<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$clients=$db->query("SELECT id,name,company FROM clients WHERE status='active' ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$client=(int)$_POST['client_id'];$name=trim((string)$_POST['name']);$desc=trim((string)$_POST['description']);$service=trim((string)$_POST['service']);$budget=max(0,(float)$_POST['budget']);$start=$_POST['start_date']?:null;$due=$_POST['due_date']?:null;$priority=in_array($_POST['priority']??'', ['low','normal','high','urgent'],true)?$_POST['priority']:'normal';if($client<1||$name==='')exit('Client and project name are required.');$number='DWS-PRJ-'.date('Ym').'-'.str_pad((string)((int)$db->query("SELECT COUNT(*) FROM client_projects WHERE DATE_FORMAT(created_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')")->fetchColumn()+1),4,'0',STR_PAD_LEFT);$token=bin2hex(random_bytes(32));$q=$db->prepare("INSERT INTO client_projects(client_id,project_number,public_token,name,description,service,budget,balance_due,start_date,due_date,priority,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,'planning')");$q->execute([$client,$number,$token,$name,$desc,$service,$budget,$budget,$start,$due,$priority]);$pid=(int)$db->lastInsertId();$db->prepare('INSERT INTO project_status_history(project_id,old_status,new_status,notes) VALUES(?,?,?,?)')->execute([$pid,null,'planning','Project created.']);header('Location: projects.php');exit;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New Project</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:850px"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h1 class="h3">Create Client Project</h1><p class="text-muted">Start the delivery record for an existing client.</p><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Client</label><select class="form-select" name="client_id" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=$e($c['name'])?><?=$c['company']?' — '.$e($c['company']):''?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Service</label><input class="form-control" name="service" placeholder="Website Development"></div><div class="col-12"><label class="form-label">Project Name</label><input class="form-control" name="name" required placeholder="Corporate Website Redesign"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description"></textarea></div><div class="col-md-4"><label class="form-label">Budget</label><input class="form-control" type="number" step="0.01" min="0" name="budget" value="0"></div><div class="col-md-4"><label class="form-label">Start Date</label><input class="form-control" type="date" name="start_date"></div><div class="col-md-4"><label class="form-label">Due Date</label><input class="form-control" type="date" name="due_date"></div><div class="col-md-6"><label class="form-label">Priority</label><select class="form-select" name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></div><div class="col-12"><button class="btn btn-dark">Create Project</button> <a class="btn btn-outline-secondary" href="projects.php">Cancel</a></div></form></div></div></main></body></html>